import{_ as t,o as a,c as o,a6 as n}from"./chunks/framework.BJFjZBwW.js";const p=JSON.parse('{"title":"RFM69 gateway","description":"","frontmatter":{},"headers":[],"relativePath":"use/rfm69.md","filePath":"use/rfm69.md","lastUpdated":1658161837000}'),r={name:"use/rfm69.md"};function i(s,e,d,m,h,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="rfm69-gateway" tabindex="-1">RFM69 gateway <a class="header-anchor" href="#rfm69-gateway" aria-label="Permalink to &quot;RFM69 gateway&quot;">​</a></h1><p>The RFM69 gateway enables to send and receive signal from/to another RFM69 module. It is based on the work of @bbx10 <a href="https://github.com/bbx10/nanohab" target="_blank" rel="noreferrer">https://github.com/bbx10/nanohab</a></p><h3 id="receiving-data-from-rfm-signal" tabindex="-1">Receiving data from RFM signal <a class="header-anchor" href="#receiving-data-from-rfm-signal" aria-label="Permalink to &quot;Receiving data from RFM signal&quot;">​</a></h3><p>Subscribe to all the messages with mosquitto or open your MQTT client software:</p><p><code> sudo mosquitto_sub -t +/# -v</code></p><p>Generate your RF signals with a Moteino on other RFM69 based devices, you will receive :</p><p><code>home/OpenMQTTGateway/RFM69toMQTT 60,-98,0</code></p><p>In this case &quot;60,-98,0&quot; is the signal sent by another RFM69 + a wemos D1 with the sample sketch <a href="https://github.com/1technophile/rfm69send/blob/master/rfm69send.ino" target="_blank" rel="noreferrer">rfm69send</a> loaded in it.</p><h3 id="send-data-by-mqtt-to-convert-it-on-rfm69-signal" tabindex="-1">Send data by MQTT to convert it on RFM69 signal <a class="header-anchor" href="#send-data-by-mqtt-to-convert-it-on-rfm69-signal" aria-label="Permalink to &quot;Send data by MQTT to convert it on RFM69 signal&quot;">​</a></h3><p><code>mosquitto_pub -t &quot;home/OpenMQTTGateway/commands/MQTTtoPilight&quot; -m &#39;{&quot;data&quot;:&quot;test&quot;}&#39;</code></p><p>This command will send by RFM69 the string <em>test</em> to the default receiver id 99</p><h3 id="send-data-by-mqtt-with-advanced-rfm69-parameters" tabindex="-1">Send data by MQTT with advanced RFM69 parameters <a class="header-anchor" href="#send-data-by-mqtt-with-advanced-rfm69-parameters" aria-label="Permalink to &quot;Send data by MQTT with advanced RFM69 parameters&quot;">​</a></h3><p>RFM69 sending support one advanced parameters the target receiver ID.</p><p>Example: SimplePublishing <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoRFM69/RCV_34 -m 33151562</code> will make the gateway send to the receiver ID 34 (node number) instead of 99</p><p>JsonPublishing <code>mosquitto_pub -t home/OpenMQTTGateway/commands/MQTTtoRFM69 -m &#39;{&quot;data&quot;:1315156,&quot;receiverid&quot;:34}&#39;</code> This command will send by RFM69 the string <em>test</em> to the receiver id 34 instead of 99</p><h3 id="rfm69-acknowledgment" tabindex="-1">RFM69 acknowledgment <a class="header-anchor" href="#rfm69-acknowledgment" aria-label="Permalink to &quot;RFM69 acknowledgment&quot;">​</a></h3><p>Unlike RF or IR RFM69 as a complete acknowledgment mechanism. When a signal is sent the RFM69 can acknowledge the fact that the recipient received the message. In this case the gateway will publish the sent message to the topic defined by subjectGTWRFM69toMQTT macro.</p>',17)])])}const u=t(r,[["render",i]]);export{p as __pageData,u as default};
